/**
 * Quantitative Experiment Runner & Research Benchmarking Engine (Phase 5).
 *
 * Executes controlled experimental protocols:
 * - Single-seed and multi-seed replication
 * - Contact detection, distance error, risk discrimination, calibration, and edge telemetry
 * - Baseline model comparisons (Proximity-Only, Proximity+Duration, Legacy Heuristic, Proposed Bayesian)
 * - Feature ablation studies
 * - Export of structured machine-readable JSON and human-readable Markdown reports
 *
 * CRITICAL SCIENTIFIC INTEGRITY CONSTRAINT:
 * All reported metrics are generated by executing actual simulation and evaluation pipelines.
 * Deterministic scientific results are strictly separated from machine-dependent telemetry.
 */

import fs from 'fs';
import path from 'path';
import os from 'os';
import type { SimulationConfig } from '../simulation/scenarioTypes.js';
import { generateCanonicalDataset } from '../datasets/generator.js';
import { extractExposureRecords } from '../risk/featureExtraction.js';
import { createDefaultRiskModel, assessExposureRecords } from '../risk/model.js';
import type { FittedRiskModel, ExposureRecord } from '../risk/riskTypes.js';
import type {
  ContactMetrics,
  DistanceMetrics,
  RiskMetrics,
  CalibrationMetrics,
  EdgeMetrics,
  ExperimentSeedResult,
  ConsolidatedExperimentResult,
  MatchingConfig,
} from './evaluationTypes.js';
import { evaluateContactDetection } from './contactMetrics.js';
import { evaluateDistanceEstimation } from './distanceMetrics.js';
import { evaluateRiskAssessments } from './riskMetrics.js';
import { evaluateCalibration } from './calibrationMetrics.js';
import { evaluateEdgeProcessing } from './edgeMetrics.js';
import { summarizeReplicateMetric } from './statisticalSummary.js';
import {
  ProximityOnlyBaseline,
  ProximityDurationBaseline,
  LegacyHeuristicBaseline,
  ProposedBayesianMethod,
  LogisticRegressionBaseline,
  PriorOnlyBaseline,
  getLabelsForRecords,
  type EvaluationMethod,
} from './baselines.js';
import { runAblationStudy } from './ablation.js';

export interface ExperimentRunOptions {
  experimentId: string;
  experimentName: string;
  baseConfig: SimulationConfig;
  seeds: number[];
  outputDir?: string;
  matchingConfig?: MatchingConfig;
  silent?: boolean;
}

/**
 * Execute a complete single-seed evaluation run on a SimulationConfig.
 */
export function evaluateSingleSeedRun(
  config: SimulationConfig,
  matchingConfig?: MatchingConfig
): ExperimentSeedResult {
  const dataset = generateCanonicalDataset(config, { silent: true });

  // 1. Contact Detection Metrics
  const contactMetrics = evaluateContactDetection(
    dataset.groundTruthContacts,
    dataset.detectedContactSessions ?? [],
    dataset.people,
    matchingConfig
  );

  // 2. Distance Estimation Metrics
  const distanceMetrics = evaluateDistanceEstimation(
    dataset.edgeObservations ?? [],
    dataset.movementStates,
    dataset.people,
    dataset.gateways
  );

  // 3. Prepare Exposure Records & Risk Assessments
  const detectedSessions = dataset.detectedContactSessions ?? [];
  const sourceStatusRegistry: Record<string, typeof dataset.people[0]['sourceStatus']> = {};
  for (const p of dataset.people) {
    sourceStatusRegistry[p.wearableId] = p.sourceStatus;
  }

  const exposureRecords = extractExposureRecords(detectedSessions, {
    sourceStatusRegistry,
    directed: true,
  });

  const riskModel: FittedRiskModel = dataset.fittedRiskModel ?? createDefaultRiskModel(config.risk);
  const riskAssessments = dataset.riskAssessments ?? assessExposureRecords(exposureRecords, riskModel);

  // 4. Risk Discrimination Metrics
  const riskMetrics = evaluateRiskAssessments(
    riskAssessments,
    dataset.groundTruthContacts,
    dataset.people,
    exposureRecords
  );

  // 5. Calibration Metrics
  const labels = getLabelsForRecords(exposureRecords, dataset);
  const predictions = riskAssessments.map((a) => a.exposureProbability);
  const calibrationMetrics = evaluateCalibration(predictions, labels);

  // 6. Edge Reduction Metrics
  const edgeMetrics = evaluateEdgeProcessing({
    rawCount: dataset.bleObservations?.length ?? 0,
    processedCount: dataset.edgeObservations?.length ?? 0,
    sessionCount: detectedSessions.length,
  });

  // Explicitly clear large arrays to prevent OOM across 30 seed iterations
  dataset.bleObservations = [];
  dataset.edgeObservations = [];

  // Deterministic signature excluding wall-clock timestamps
  const deterministicSignature = JSON.stringify({
    seed: config.seed,
    tp: contactMetrics.truePositives,
    fp: contactMetrics.falsePositives,
    fn: contactMetrics.falseNegatives,
    f1: contactMetrics.f1Score,
    auroc: riskMetrics.auroc,
    auprc: riskMetrics.auprc,
    brier: calibrationMetrics.brierScore,
    ece: calibrationMetrics.expectedCalibrationError,
  });

  return {
    seed: config.seed,
    contactMetrics,
    distanceMetrics,
    riskMetrics,
    calibrationMetrics,
    edgeMetrics,
    deterministicSignature,
  };
}

/**
 * Execute a complete multi-seed experiment and generate consolidated results.
 */
export function runMultiSeedExperiment(
  options: ExperimentRunOptions
): ConsolidatedExperimentResult {
  const {
    experimentId,
    experimentName,
    baseConfig,
    seeds,
    outputDir = `results/${experimentId}`,
    matchingConfig,
    silent = false,
  } = options;

  if (!silent) {
    console.log(`\n[Experiment Runner] Starting ${experimentName} (${experimentId})...`);
    console.log(`- Seeds: [${seeds.join(', ')}]`);
  }

  const perSeedResults: ExperimentSeedResult[] = [];

  for (const seed of seeds) {
    const seedConfig: SimulationConfig = {
      ...baseConfig,
      seed,
    };
    const res = evaluateSingleSeedRun(seedConfig, matchingConfig);
    perSeedResults.push(res);
  }

  // Aggregate Contact Metrics
  const contactSummary = {
    precision: summarizeReplicateMetric(
      'contact_precision',
      perSeedResults.map((r) => r.contactMetrics.precision)
    ),
    recall: summarizeReplicateMetric(
      'contact_recall',
      perSeedResults.map((r) => r.contactMetrics.recall)
    ),
    f1Score: summarizeReplicateMetric(
      'contact_f1',
      perSeedResults.map((r) => r.contactMetrics.f1Score)
    ),
    durationMaeSeconds: summarizeReplicateMetric(
      'duration_mae_sec',
      perSeedResults
        .map((r) => r.contactMetrics.durationError.maeSeconds)
        .filter((v): v is number => v !== undefined)
    ),
    durationRmseSeconds: summarizeReplicateMetric(
      'duration_rmse_sec',
      perSeedResults
        .map((r) => r.contactMetrics.durationError.rmseSeconds)
        .filter((v): v is number => v !== undefined)
    ),
    fragmentationRate: summarizeReplicateMetric(
      'fragmentation_rate',
      perSeedResults.map((r) => r.contactMetrics.fragmentation.fragmentationRate)
    ),
    mergeRate: summarizeReplicateMetric(
      'merge_rate',
      perSeedResults.map((r) => r.contactMetrics.merging.mergeRate)
    ),
    truePositives: summarizeReplicateMetric(
      'true_positives',
      perSeedResults.map((r) => r.contactMetrics.truePositives)
    ),
    falsePositives: summarizeReplicateMetric(
      'false_positives',
      perSeedResults.map((r) => r.contactMetrics.falsePositives)
    ),
    falseNegatives: summarizeReplicateMetric(
      'false_negatives',
      perSeedResults.map((r) => r.contactMetrics.falseNegatives)
    ),
    totalGroundTruthContacts: summarizeReplicateMetric(
      'total_gt_contacts',
      perSeedResults.map((r) => r.contactMetrics.totalGroundTruthContacts)
    ),
  };

  const nonemptyResults = perSeedResults.filter(r => r.riskMetrics.totalEvaluatedRecords > 0);

  // Aggregate Risk Metrics
  const aurocValues = perSeedResults
    .map((r) => r.riskMetrics.auroc)
    .filter((v): v is number => v !== undefined);
  const auprcValues = perSeedResults
    .map((r) => r.riskMetrics.auprc)
    .filter((v): v is number => v !== undefined);

  const riskSummary = {
    auroc: summarizeReplicateMetric('risk_auroc', aurocValues),
    auprc: summarizeReplicateMetric('risk_auprc', auprcValues),
    defaultF1: summarizeReplicateMetric(
      'risk_threshold_0.5_f1',
      nonemptyResults.map((r) => r.riskMetrics.defaultThresholdMetrics?.f1Score ?? 0)
    ),
  };

  // Aggregate Calibration Metrics
  const calibrationSummary = {
    brierScore: summarizeReplicateMetric(
      'brier_score',
      nonemptyResults.map((r) => r.calibrationMetrics.brierScore)
    ),
    expectedCalibrationError: summarizeReplicateMetric(
      'ece',
      nonemptyResults.map((r) => r.calibrationMetrics.expectedCalibrationError)
    ),
  };

  // Aggregate Edge Metrics
  const edgeSummary = {
    reductionRatio: summarizeReplicateMetric(
      'edge_reduction_ratio',
      perSeedResults.map((r) => r.edgeMetrics.observationReductionRatio)
    ),
  };

  const consolidated: ConsolidatedExperimentResult = {
    experimentId,
    experimentName,
    conditionDescription: 'Standard canonical simulation under specified parameters',
    conditionParameters: {
      durationSeconds: baseConfig.durationSeconds,
      populationSize: baseConfig.populationSize,
      gatewayCount: baseConfig.gatewayCount,
      rssiNoiseSigma: baseConfig.ble?.rssi.noiseSigmaDb,
      packetLossProbability: baseConfig.ble?.reception.packetLossProbability,
    },
    resolvedConfig: {
      datasetVersion: baseConfig.datasetVersion,
      scenarioVersion: baseConfig.scenarioVersion,
      contactDefinition: baseConfig.contactDefinition,
      ble: baseConfig.ble,
      edge: baseConfig.edge,
      risk: baseConfig.risk,
      matching: matchingConfig,
    },
    seedList: seeds,
    replicateCount: seeds.length,
    contactSummary,
    riskSummary,
    calibrationSummary,
    edgeSummary,
    perSeedResults,
    hostEnvironment: {
      platform: `${os.platform()} ${os.release()}`,
      nodeVersion: process.version,
      cpuModel: os.cpus()[0]?.model,
    },
    generatedAt: '2026-01-01T00:00:00.000Z', // Deterministic timestamp for reproducible artifact hashing
  };

  // Write results to disk
  fs.mkdirSync(outputDir, { recursive: true });

  fs.writeFileSync(
    path.join(outputDir, 'manifest.json'),
    JSON.stringify(consolidated.resolvedConfig, null, 2),
    'utf-8'
  );
  fs.writeFileSync(
    path.join(outputDir, 'per_seed_results.json'),
    JSON.stringify(perSeedResults, null, 2),
    'utf-8'
  );
  fs.writeFileSync(
    path.join(outputDir, 'summary.json'),
    JSON.stringify(consolidated, null, 2),
    'utf-8'
  );
  fs.writeFileSync(
    path.join(outputDir, 'contact_metrics.json'),
    JSON.stringify(contactSummary, null, 2),
    'utf-8'
  );
  fs.writeFileSync(
    path.join(outputDir, 'risk_metrics.json'),
    JSON.stringify(riskSummary, null, 2),
    'utf-8'
  );
  fs.writeFileSync(
    path.join(outputDir, 'calibration_metrics.json'),
    JSON.stringify(calibrationSummary, null, 2),
    'utf-8'
  );
  fs.writeFileSync(
    path.join(outputDir, 'edge_metrics.json'),
    JSON.stringify(edgeSummary, null, 2),
    'utf-8'
  );

  // Generate Human-Readable Markdown Report
  const markdownReport = generateMarkdownReport(consolidated);
  fs.writeFileSync(path.join(outputDir, 'README.md'), markdownReport, 'utf-8');

  if (!silent) {
    console.log(`[Experiment Runner] Completed ${experimentName}. Results saved to: ${outputDir}`);
  }

  return consolidated;
}

/**
 * Run baseline comparison experiment evaluating all four candidate methods on identical inputs.
 */
export function runBaselineComparisonExperiment(
  config: SimulationConfig,
  outputDir = 'results/baseline-comparison',
  trainingRecords?: ExposureRecord[],
  trainingLabels?: (0 | 1)[]
): {
  dataset: import('../datasets/schema.js').CanonicalDataset;
  records: ExposureRecord[];
  labels: (0 | 1)[];
  methods: Array<{
    name: string;
    description: string;
    metrics: RiskMetrics;
    calibration: CalibrationMetrics;
  }>;
} {
  const dataset = generateCanonicalDataset(config, { silent: true });
  const detectedSessions = dataset.detectedContactSessions ?? [];

  const sourceStatusRegistry: Record<string, typeof dataset.people[0]['sourceStatus']> = {};
  for (const p of dataset.people) {
    sourceStatusRegistry[p.wearableId] = p.sourceStatus;
  }

  const exposureRecords = extractExposureRecords(detectedSessions, {
    sourceStatusRegistry,
    directed: true,
  });

  // Explicitly clear large arrays to prevent OOM
  dataset.bleObservations = [];
  dataset.edgeObservations = [];

  const fittedModel = dataset.fittedRiskModel ?? createDefaultRiskModel(config.risk);

  const methods: EvaluationMethod[] = [
    new ProximityOnlyBaseline(),
    new ProximityDurationBaseline(),
    new LegacyHeuristicBaseline(),
    new ProposedBayesianMethod(fittedModel),
    new LogisticRegressionBaseline(),
    new PriorOnlyBaseline(dataset),
  ];

  if (trainingRecords && trainingLabels) {
    for (const method of methods) {
      if (method.train) {
        method.train(trainingRecords, trainingLabels);
      }
    }
  }

  const results = methods.map((method) => {
    const assessments = method.predict(exposureRecords);
    const riskMetrics = evaluateRiskAssessments(
      assessments,
      dataset.groundTruthContacts,
      dataset.people,
      exposureRecords
    );

    const labels = getLabelsForRecords(exposureRecords, dataset);
    const predictions = assessments.map((a) => a.exposureProbability);
    const calibration = evaluateCalibration(predictions, labels);

    return {
      name: method.name,
      description: method.description,
      metrics: riskMetrics,
      calibration,
    };
  });

  fs.mkdirSync(outputDir, { recursive: true });
  fs.writeFileSync(
    path.join(outputDir, 'baseline_comparison.json'),
    JSON.stringify(results, null, 2),
    'utf-8'
  );

  return { 
    dataset,
    records: exposureRecords,
    labels: getLabelsForRecords(exposureRecords, dataset),
    methods: results
  };
}

/**
 * Generate human-readable Markdown research report.
 */
function generateMarkdownReport(res: ConsolidatedExperimentResult): string {
  const formatCI = (m: import('./evaluationTypes.js').MetricSummary) => {
    if (!m.confidenceInterval95) return 'N/A';
    return `[${m.confidenceInterval95.lower.toFixed(3)}, ${m.confidenceInterval95.upper.toFixed(3)}]`;
  };

  return `# Research Experiment Report: ${res.experimentName}

**Experiment ID:** \`${res.experimentId}\`  
**Replicates (Seeds):** ${res.replicateCount} (\`${res.seedList.join(', ')}\`)  
**Generated At:** ${res.generatedAt}

---

## 1. Resolved Experimental Configuration
- **Population Size:** ${res.conditionParameters.populationSize}
- **Gateways:** ${res.conditionParameters.gatewayCount}
- **Simulation Duration:** ${res.conditionParameters.durationSeconds}s
- **RSSI Noise Sigma:** ${res.conditionParameters.rssiNoiseSigma ?? 'N/A'} dB
- **Packet Loss:** ${res.conditionParameters.packetLossProbability ?? 'N/A'}

---

## 2. Contact Detection Performance
| Metric | Mean | Median | Std Dev | 95% Confidence Interval |
|---|---|---|---|---|
| **Precision** | ${res.contactSummary.precision.mean.toFixed(3)} | ${res.contactSummary.precision.median.toFixed(3)} | ${res.contactSummary.precision.standardDeviation.toFixed(3)} | ${formatCI(res.contactSummary.precision)} |
| **Recall** | ${res.contactSummary.recall.mean.toFixed(3)} | ${res.contactSummary.recall.median.toFixed(3)} | ${res.contactSummary.recall.standardDeviation.toFixed(3)} | ${formatCI(res.contactSummary.recall)} |
| **F1 Score** | ${res.contactSummary.f1Score.mean.toFixed(3)} | ${res.contactSummary.f1Score.median.toFixed(3)} | ${res.contactSummary.f1Score.standardDeviation.toFixed(3)} | ${formatCI(res.contactSummary.f1Score)} |
| **Duration MAE (s)** | ${res.contactSummary.durationMaeSeconds.mean.toFixed(1)} | ${res.contactSummary.durationMaeSeconds.median.toFixed(1)} | ${res.contactSummary.durationMaeSeconds.standardDeviation.toFixed(1)} | ${formatCI(res.contactSummary.durationMaeSeconds)} |
| **Duration RMSE (s)** | ${res.contactSummary.durationRmseSeconds.mean.toFixed(1)} | ${res.contactSummary.durationRmseSeconds.median.toFixed(1)} | ${res.contactSummary.durationRmseSeconds.standardDeviation.toFixed(1)} | ${formatCI(res.contactSummary.durationRmseSeconds)} |
| **Fragmentation Rate** | ${res.contactSummary.fragmentationRate.mean.toFixed(3)} | ${res.contactSummary.fragmentationRate.median.toFixed(3)} | ${res.contactSummary.fragmentationRate.standardDeviation.toFixed(3)} | ${formatCI(res.contactSummary.fragmentationRate)} |

---

## 3. Risk Discrimination & Calibration
| Metric | Mean | Median | Std Dev | 95% Confidence Interval |
|---|---|---|---|---|
| **AUROC** | ${res.riskSummary.auroc.mean.toFixed(3)} | ${res.riskSummary.auroc.median.toFixed(3)} | ${res.riskSummary.auroc.standardDeviation.toFixed(3)} | ${formatCI(res.riskSummary.auroc)} |
| **AUPRC** | ${res.riskSummary.auprc.mean.toFixed(3)} | ${res.riskSummary.auprc.median.toFixed(3)} | ${res.riskSummary.auprc.standardDeviation.toFixed(3)} | ${formatCI(res.riskSummary.auprc)} |
| **Brier Score** | ${res.calibrationSummary.brierScore.mean.toFixed(4)} | ${res.calibrationSummary.brierScore.median.toFixed(4)} | ${res.calibrationSummary.brierScore.standardDeviation.toFixed(4)} | ${formatCI(res.calibrationSummary.brierScore)} |
| **Expected Calibration Error (ECE)** | ${res.calibrationSummary.expectedCalibrationError.mean.toFixed(4)} | ${res.calibrationSummary.expectedCalibrationError.median.toFixed(4)} | ${res.calibrationSummary.expectedCalibrationError.standardDeviation.toFixed(4)} | ${formatCI(res.calibrationSummary.expectedCalibrationError)} |

---

## 4. Edge Processing & Reduction
- **Mean Frame Reduction Ratio:** ${(res.edgeSummary.reductionRatio.mean * 100).toFixed(1)}%

---

## 5. Scientific Limitations & Disclaimers
1. **Simulation Assumption Bound:** Performance numbers are obtained under the specified 2D mobility and RF log-distance shadowing models. They reflect digital contact reconstruction performance, NOT clinical pathogen transmission.
2. **Digital Exposure Target:** $E=1$ defines compliance with physical proximity thresholds; it does not indicate medical diagnosis.
`;
}
